    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}
_FULL_MONTHS = {
    "january": 1, "february": 2, "march": 3, "april": 4, "may": 5, "june": 6,
    "july": 7, "august": 8, "september": 9, "october": 10, "november": 11, "december": 12,
}

_ISO_RE = re.compile(r"(\d{4})-(\d{2})-(\d{2})")
_DAY_MONTH_RE = re.compile(r"(\d{1,2}) ([A-Za-z]{3}) (\d{4})")
_MONTH_DAY_RE = re.compile(r"([A-Za-z]+) (\d{1,2}), (\d{4})")
_SLASH_RE = re.compile(r"(\d{2})/(\d{2})/(\d{4})")


def _format_iso(year: int, month: int, day: int) -> str | None:
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return None


def handle_normalize_date(params: dict) -> tuple[int, dict]:
    raw = params.get("date")
    if not isinstance(raw, str):
        return 400, {"error": "invalid date"}
    text = raw.strip()

    match = _ISO_RE.fullmatch(text)
    if match:
        result = _format_iso(int(match[1]), int(match[2]), int(match[3]))
    elif (match := _DAY_MONTH_RE.fullmatch(text)):
        month = _MONTHS.get(match[2].lower())
        result = _format_iso(int(match[3]), month, int(match[1])) if month else None
    elif (match := _MONTH_DAY_RE.fullmatch(text)):
        month = _FULL_MONTHS.get(match[1].lower())
        result = _format_iso(int(match[3]), month, int(match[2])) if month else None
    elif (match := _SLASH_RE.fullmatch(text)):
        result = _format_iso(int(match[3]), int(match[2]), int(match[1]))
    else:
        result = None

    if result is None:
        return 400, {"error": "invalid date"}
    return 200, {"date": result}


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user
"}

